script:
frappe.ui.form.on('Sabre Sales Opportunity', {

    // عند فتح الفورم
    refresh(frm) {
        // إخفاء expected_revenue في البداية
        frm.toggle_display('expected_revenue', false);
        
        // تشغيل trigger الخاص بـ opportunity_type
        if (frm.doc.opportunity_type) {
            frm.trigger('opportunity_type');
        }
    },

    // عند تغيير نوع الفرصة
    opportunity_type(frm) {
        if (frm.doc.opportunity_type === 'Renewal') {
            // إظهار Expected Revenue فقط عند Renewal
            frm.toggle_display('expected_revenue', true);
            frm.set_df_property('expected_revenue', 'reqd', 1);
        } else {
            frm.toggle_display('expected_revenue', false);
            frm.set_df_property('expected_revenue', 'reqd', 0);
        }
    },

    // عند تغيير assigned_to
    assigned_to(frm) {
        if (frm.doc.assigned_to === 'Product') {
            frm.set_value('pipeline_am', '');
            frappe.msgprint("تم تعيين المسؤول للـ Product Team");
        }
    }

});

frappe.ui.form.on('Sabre Qualification Checklist', {

    // عند فتح الفورم
    refresh(frm) {
        // إخفاء reason_code في البداية
        frm.toggle_display('reason_code', false);

        // تشغيل trigger الخاص بـ qualified
        if (frm.doc.qualified) {
            frm.trigger('qualified');
        }
    },

    // عند تغيير نتيجة التأهيل
    qualified(frm) {
        if (frm.doc.qualified === 'No') {
            // إظهار Reason Code وجعله إلزامي
            frm.toggle_display('reason_code', true);
            frm.set_df_property('reason_code', 'reqd', 1);
        } else {
            // إخفاء Reason Code
            frm.toggle_display('reason_code', false);
            frm.set_df_property('reason_code', 'reqd', 0);
            frm.set_value('reason_code', '');
        }
    },

    // عند اختيار الـ Opportunity
    opportunity(frm) {
        if (frm.doc.opportunity) {
            // جلب بيانات الـ Opportunity تلقائياً
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frappe.show_alert({
                            message: `Customer: ${data.customer} | AM: ${data.pipeline_am}`,
                            indicator: 'blue'
                        });
                    }
                }
            );
        }
    }

});
